BOOST_AUTO_TEST_CASE(bip39_vectors)
{
    for (const TestVector& test : vectors) {
        std::string mnemonic, language, error;
        BOOST_REQUIRE(bip39::Normalize(test.mnemonic, true, mnemonic));
        BOOST_CHECK_MESSAGE(bip39::CheckMnemonic(mnemonic, language, error), error);
        const std::vector<unsigned char> seed = bip39::MnemonicToSeed(mnemonic, "TREZOR");
        BOOST_CHECK_EQUAL(HexStr(seed), test.seed);

        // The root key is serialized with the Bitcoin version bytes, which
        // mainnet shares
        CExtKey master;
        master.SetSeed(seed.data(), seed.size());
        CAokChainExtKey b58key;
        b58key.SetKey(master);
        BOOST_CHECK_EQUAL(b58key.ToString(), test.xprv);
    }
}

BOOST_AUTO_TEST_CASE(bip39_normalize)
{
    std::string out;
    // whitespace and case
    BOOST_CHECK(bip39::Normalize("  Abandon\tABOUT \n", true, out));
    BOOST_CHECK_EQUAL(out, "abandon about");
    // a passphrase is taken as it is
    BOOST_CHECK(bip39::Normalize(" Pass Word ", false, out));
    BOOST_CHECK_EQUAL(out, " Pass Word ");
    // Hangul syllables decompose: U+AC00 (L V) and U+AC01 (L V T)
    BOOST_CHECK(bip39::Normalize("\xea\xb0\x80\xea\xb0\x81", true, out));
    BOOST_CHECK_EQUAL(out, "\xe1\x84\x80\xe1\x85\xa1\xe1\x84\x80\xe1\x85\xa1\xe1\x86\xa8");
    // the ideographic space separates words
    BOOST_CHECK(bip39::Normalize("a\xe3\x80\x80" "b", true, out));
    BOOST_CHECK_EQUAL(out, "a b");
    // text that would need a real NFKD implementation is refused
    BOOST_CHECK(!bip39::Normalize("caf\xc3\xa9", true, out));
    // malformed UTF-8
    BOOST_CHECK(!bip39::Normalize("\xff", true, out));
    BOOST_CHECK(!bip39::Normalize("\xe1\x84", true, out));
}

BOOST_AUTO_TEST_CASE(bip39_check)
{
    std::string language, error;
    BOOST_CHECK(bip39::CheckMnemonic("abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about", language, error));
    BOOST_CHECK_EQUAL(language, "english");
    // wrong checksum
    BOOST_CHECK(!bip39::CheckMnemonic("abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon", language, error));
    // unknown word
    BOOST_CHECK(!bip39::CheckMnemonic("abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abouty", language, error));
    BOOST_CHECK(error.find("word 12") != std::string::npos);
    // wrong number of words
    BOOST_CHECK(!bip39::CheckMnemonic("abandon about", language, error));
    BOOST_CHECK(!bip39::CheckMnemonic("", language, error));
}

BOOST_AUTO_TEST_CASE(bip39_path)
{
    std::vector<uint32_t> path;
    BOOST_CHECK(bip39::ParsePath("m/44'/0h/0'/0", path));
    BOOST_CHECK(path == std::vector<uint32_t>({0x8000002C, 0x80000000, 0x80000000, 0}));
    BOOST_CHECK_EQUAL(bip39::FormatPath(path), "m/44'/0'/0'/0");
    BOOST_CHECK(bip39::ParsePath("m", path));
    BOOST_CHECK(path.empty());
    BOOST_CHECK(!bip39::ParsePath("", path));
    BOOST_CHECK(!bip39::ParsePath("44'/0'", path));
    BOOST_CHECK(!bip39::ParsePath("m/", path));
    BOOST_CHECK(!bip39::ParsePath("m/2147483648", path));
    BOOST_CHECK(!bip39::ParsePath("m/1//2", path));
    BOOST_CHECK(!bip39::ParsePath("m/1x", path));
}

